-- pup_tailor install script. Safe to run more than once.
-- The resource also creates its two tables on start if they are missing.

CREATE TABLE IF NOT EXISTS `palette_names` (
    `palette` BIGINT(20) NOT NULL,
    `name` VARCHAR(24) NOT NULL,
    PRIMARY KEY (`palette`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `clothing_hidden` (
    `drawable` INT(11) NOT NULL,
    `label` VARCHAR(96) NULL DEFAULT NULL,
    `hidden_by` VARCHAR(96) NULL DEFAULT NULL,
    `hidden_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`drawable`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

